// Normalise the Gmail trigger output (works with "Simplify" on or off)
const s = $('Settings').first().json;
const max = Number(s.max_body_chars) || 6000;
// (Settings replaces the item, so read the emails straight from the trigger node)
return $('Gmail Trigger').all().map(item => {
  const m = item.json;
  const fromAddr = m.from?.value?.[0]?.address || m.From || m.from?.text || '';
  const fromName = m.from?.value?.[0]?.name || '';
  const body = (m.text || m.snippet || '').toString().replace(/\n{3,}/g, '\n\n').slice(0, max);
  return { json: {
    messageId: m.id, threadId: m.threadId,
    from: fromAddr, fromName,
    subject: m.subject || m.Subject || '(no subject)',
    body, date: m.date || new Date().toISOString(),
  }};
});

// Parse the model's JSON. Anything invalid falls back to "other" so nothing is lost.
const CATS = ['urgent','sales_lead','support','billing','newsletter_spam','other'];
const PRI = ['high','medium','low'];
const emails = $('Prepare Email').all();
return $input.all().map((item, i) => {
  let r = item.json;
  // OpenAI node (Responses API) simplified output: output[0].content[0].text
  let out = r?.output?.[0]?.content?.[0]?.text ?? r?.message?.content ?? r?.text ?? r;
  if (typeof out === 'string') {
    const raw = out;
    try { out = JSON.parse(raw.replace(/^```(json)?|```$/g, '').trim()); }
    catch (e) { // fallback for "key: value" style answers
      out = {};
      for (const m of raw.matchAll(/^\s*"?(category|priority|summary|reason|needs_reply)"?\s*[:=]\s*"?(.+?)"?\s*,?\s*$/gim)) out[m[1].toLowerCase()] = m[2].trim();
      if (typeof out.category === 'string') out.category = out.category.toLowerCase();
      if (typeof out.priority === 'string') out.priority = out.priority.toLowerCase();
      out.needs_reply = String(out.needs_reply).toLowerCase() === 'true';
    }
  }
  out = out || {};
  const category = CATS.includes(out.category) ? out.category : 'other';
  const priority = PRI.includes(out.priority) ? out.priority : 'medium';
  return { json: {
    ...emails[i].json,
    category, priority,
    summary: String(out.summary || '').slice(0, 300),
    needs_reply: Boolean(out.needs_reply),
    reason: String(out.reason || (CATS.includes(out.category) ? '' : 'fallback: unparseable model output')),
  }};
});

// Map category -> Gmail label ID. Labels must exist in Gmail, named <prefix><Name>, e.g. "AI/Urgent".
const s = $('Settings').first().json;
const prefix = s.label_prefix ?? 'AI/';
const NAMES = { urgent:'Urgent', sales_lead:'Sales Lead', support:'Support', billing:'Billing', newsletter_spam:'Newsletter-Spam', other:'Other' };
const labels = $('Get Gmail Labels').all().map(l => l.json);
const byName = {};
for (const l of labels) if (l && l.name) byName[l.name.toLowerCase()] = l.id;
const results = $('Parse Classification').all().map(item => {
  const e = item.json;
  const labelName = prefix + NAMES[e.category];
  const priName = prefix + 'Priority-' + e.priority[0].toUpperCase() + e.priority.slice(1);
  const labelIds = [byName[labelName.toLowerCase()]];
  if (s.add_priority_labels && byName[priName.toLowerCase()]) labelIds.push(byName[priName.toLowerCase()]);
  return { json: { ...e, labelName, labelIds: labelIds.filter(Boolean),
    labelMissing: !byName[labelName.toLowerCase()] } };
});
return results;
